// Explicit zero-prior-usage budget for synthetic mocked tests only. Not production initialization.
import{openUploadApi as actual}from'../../src/server/open-upload';import{sharedSpendApi,sharedSpendClient,type SharedSpend}from'../../src/server/shared-spend';import type{Store}from'../../src/server/hosted';
class Memory implements Store{data=new Map<string,unknown>();tail=Promise.resolve();async get<T>(k:string){return structuredClone(this.data.get(k))as T|undefined;}async put<T>(k:string,v:T){this.data.set(k,structuredClone(v));}async transaction<T>(f:(s:Store)=>Promise<T>){const old=this.tail;let release!:()=>void;this.tail=new Promise(r=>release=r);await old;try{return await f(this);}finally{release();}}}
const budgets=new WeakMap<Store,SharedSpend>();export function fixtureSharedBudget(store:Store,origin:string){let client=budgets.get(store);if(!client){const global=new Memory();client=sharedSpendClient({idFromName:n=>n,get:()=>({fetch:r=>sharedSpendApi(r,{WARDROBE_ORDINARY_MODE:'open',WARDROBE_ORDINARY_PRIOR_SPEND_MICRO_USD:'0',WARDROBE_ORDINARY_BUDGET_BASELINE_ACK:'prior-usage-reviewed-v1'},global)})},origin);budgets.set(store,client);}return client;}
export const openUploadApi:typeof actual=(request,env,store,options={})=>actual(request,env,store,{...options,sharedBudget:options.sharedBudget??fixtureSharedBudget(store,new URL(request.url).origin)});
